/**
 * CandlestickChart.js - Interactive Candlestick Chart
 * Premium trading chart with predictions
 */

import React, { useEffect, useRef } from 'react';
import { createChart } from 'lightweight-charts';

const CandlestickChart = ({ ticker, currentPrice, predictedPrice }) => {
  const chartContainerRef = useRef();
  const chartRef = useRef();

  useEffect(() => {
    if (!chartContainerRef.current) return;

    // Create chart
    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: 400,
      layout: {
        background: { color: 'transparent' },
        textColor: '#d1d5db',
      },
      grid: {
        vertLines: { color: 'rgba(255, 255, 255, 0.05)' },
        horzLines: { color: 'rgba(255, 255, 255, 0.05)' },
      },
      crosshair: {
        mode: 1,
      },
      rightPriceScale: {
        borderColor: 'rgba(255, 255, 255, 0.1)',
      },
      timeScale: {
        borderColor: 'rgba(255, 255, 255, 0.1)',
        timeVisible: true,
      },
    });

    chartRef.current = chart;

    // Generate sample candlestick data (last 60 days)
    const candleData = generateCandleData(currentPrice, 60);
    
    // Add candlestick series
    const candleSeries = chart.addCandlestickSeries({
      upColor: '#10b981',
      downColor: '#ef4444',
      borderUpColor: '#10b981',
      borderDownColor: '#ef4444',
      wickUpColor: '#10b981',
      wickDownColor: '#ef4444',
    });
    candleSeries.setData(candleData);

    // Add SMA 20 line
    const sma20Data = calculateSMA(candleData, 20);
    const sma20Series = chart.addLineSeries({
      color: '#3b82f6',
      lineWidth: 2,
      title: 'SMA 20',
    });
    sma20Series.setData(sma20Data);

    // Add SMA 50 line
    const sma50Data = calculateSMA(candleData, 50);
    const sma50Series = chart.addLineSeries({
      color: '#8b5cf6',
      lineWidth: 2,
      title: 'SMA 50',
    });
    sma50Series.setData(sma50Data);

    // Add prediction marker
    const lastTime = candleData[candleData.length - 1].time;
    const predictionTime = lastTime + 86400; // Next day
    
    const predictionSeries = chart.addLineSeries({
      color: '#f59e0b',
      lineWidth: 3,
      lineStyle: 2, // Dashed
      title: 'Prediction',
    });
    
    predictionSeries.setData([
      { time: lastTime, value: currentPrice },
      { time: predictionTime, value: predictedPrice },
    ]);

    // Add volume series
    const volumeData = candleData.map(d => ({
      time: d.time,
      value: d.volume,
      color: d.close > d.open ? 'rgba(16, 185, 129, 0.3)' : 'rgba(239, 68, 68, 0.3)',
    }));

    const volumeSeries = chart.addHistogramSeries({
      color: '#26a69a',
      priceFormat: {
        type: 'volume',
      },
      priceScaleId: 'volume',
    });
    volumeSeries.setData(volumeData);

    chart.priceScale('volume').applyOptions({
      scaleMargins: {
        top: 0.8,
        bottom: 0,
      },
    });

    // Handle resize
    const handleResize = () => {
      if (chartContainerRef.current) {
        chart.applyOptions({
          width: chartContainerRef.current.clientWidth,
        });
      }
    };

    window.addEventListener('resize', handleResize);

    // Fit content
    chart.timeScale().fitContent();

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [currentPrice, predictedPrice]);

  return (
    <div 
      ref={chartContainerRef} 
      style={{ 
        position: 'relative', 
        width: '100%',
        borderRadius: '12px',
        overflow: 'hidden'
      }} 
    />
  );
};

// Helper: Generate sample candlestick data
function generateCandleData(basePrice, days) {
  const data = [];
  let price = basePrice * 0.85; // Start 15% lower
  const now = Math.floor(Date.now() / 1000);
  const dayInSeconds = 86400;

  for (let i = days; i >= 0; i--) {
    const time = now - (i * dayInSeconds);
    const open = price;
    const volatility = price * 0.02; // 2% volatility
    const close = open + (Math.random() - 0.48) * volatility;
    const high = Math.max(open, close) + Math.random() * volatility * 0.5;
    const low = Math.min(open, close) - Math.random() * volatility * 0.5;
    const volume = Math.random() * 10000000 + 5000000;

    data.push({ 
      time, 
      open, 
      high, 
      low, 
      close,
      volume
    });

    price = close;
  }

  return data;
}

// Helper: Calculate Simple Moving Average
function calculateSMA(data, period) {
  const sma = [];
  
  for (let i = period - 1; i < data.length; i++) {
    let sum = 0;
    for (let j = 0; j < period; j++) {
      sum += data[i - j].close;
    }
    sma.push({
      time: data[i].time,
      value: sum / period,
    });
  }
  
  return sma;
}

export default CandlestickChart;
